package com.lmspilot.learning.domain; import java.util.*; import org.springframework.data.jpa.repository.JpaRepository;
public interface AssignmentSubmissionRepository extends JpaRepository<AssignmentSubmissionEntity,UUID>{ List<AssignmentSubmissionEntity> findAllByUserIdOrderBySubmittedAtDesc(UUID userId); List<AssignmentSubmissionEntity> findAllByEnrollmentIdAndLessonIdOrderByAttemptNoDesc(UUID enrollmentId,UUID lessonId); List<AssignmentSubmissionEntity> findAllByCourseIdInAndStatusOrderBySubmittedAtAsc(Set<UUID> courseIds,AssignmentSubmissionStatus status); long countByEnrollmentIdAndLessonId(UUID enrollmentId,UUID lessonId); }
